namespace sv_bff0b3cbadb74529bc2b9202d928c2dc.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile</h2>

    @if (_loading)
    {
        <p>Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <div class="avatar-image">
                    @if (!string.IsNullOrEmpty(_avatarUrl))
                    {
                        <img src="@_avatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">No Avatar</div>
                    }
                </div>
                <label>Avatar URL</label>
                <input type="url" @bind="_avatarUrl" @bind:event="oninput" placeholder="https://example.com/avatar.png" />
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" @bind="_displayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" @bind="_email" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea rows="4" @bind="_bio" @bind:event="oninput"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn-secondary" @onclick="Discard" disabled="@_saving">
                    Discard Changes
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Profile saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private string _savedDisplayName = "";
    private string _savedEmail = "";
    private string _savedAvatarUrl = "";
    private string _savedBio = "";

    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        ApplyProfile(profile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = _savedDisplayName = profile.DisplayName;
        _email = _savedEmail = profile.Email;
        _avatarUrl = _savedAvatarUrl = profile.AvatarUrl;
        _bio = _savedBio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);

        _savedDisplayName = _displayName;
        _savedEmail = _email;
        _savedAvatarUrl = _avatarUrl;
        _savedBio = _bio;

        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private void Discard()
    {
        _displayName = _savedDisplayName;
        _email = _savedEmail;
        _avatarUrl = _savedAvatarUrl;
        _bio = _savedBio;
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p>Loading notification preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <div class="muted-channels">
                <h3>Muted Channels</h3>
                @if (_allChannels.Count == 0)
                {
                    <p class="text-muted">No channels available.</p>
                }
                else
                {
                    @foreach (var channel in _allChannels)
                    {
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@_mutedChannels.Contains(channel)"
                                   @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                            <span>@channel</span>
                        </label>
                    }
                }
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new();

    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _allChannels = new List<string> { "general", "announcements", "engineering", "design", "marketing", "support" };
        _loading = false;
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <div class="security-form">
            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-toggle">@(_passwordPanelOpen ? "▾" : "▸")</span>
                </button>

                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm New Password</label>
                            <input type="password" @bind="_confirmPassword" />
                        </div>

                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="toast toast-error">@_passwordError</div>
                        }
                        @if (_passwordSuccess)
                        {
                            <div class="toast toast-success">Password updated successfully!</div>
                        }

                        <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                            @(_changingPassword ? "Updating..." : "Update Password")
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="tfa-section">
                <h3>Two-Factor Authentication</h3>
                <div class="tfa-status">
                    <span class="status-indicator @(_twoFactorEnabled ? "status-active" : "status-inactive")"></span>
                    <span>@(_twoFactorEnabled ? "Enabled" : "Disabled")</span>
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_twoFactorEnabled" />
                        <span class="toggle-switch"></span>
                    </label>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <p class="text-muted">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <!-- Active Sessions -->
            <div class="sessions-section">
                <h3>Active Sessions</h3>
                @if (_sessions.Count == 0)
                {
                    <p class="text-muted">No active sessions.</p>
                }
                else
                {
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _sessions.First())
                                        {
                                            @if (_confirmingRevokeId == session.Id)
                                            {
                                                <span class="revoke-confirm">
                                                    <span>Revoke?</span>
                                                    <button class="btn-danger btn-sm" @onclick="() => RevokeSessionAsync(session.Id)">Yes</button>
                                                    <button class="btn-secondary btn-sm" @onclick="() => _confirmingRevokeId = null">No</button>
                                                </span>
                                            }
                                            else
                                            {
                                                <button class="btn-danger btn-sm" @onclick="() => _confirmingRevokeId = session.Id">Revoke</button>
                                            }
                                        }
                                        else
                                        {
                                            <span class="current-session-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                }
            </div>
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();

    // Password change state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordError;
    private bool _passwordSuccess;

    // Session revoke state
    private string? _confirmingRevokeId;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _changingPassword = true;

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
