                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="live-preview @GetPreviewClasses()">
                <h4>Preview</h4>
                <p>This is how your content will appear with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Preview text showing theme, font size, and spacing changes.</p>
                    <button class="btn-primary">Action Button</button>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
